def avoid_ships(n, m, ships):
    # Sort ships by their y-coordinate
    ships.sort(key=lambda ship: ship[2])

    # Initialize the torpedo's position
    x, y = 0, 0

    # Initialize the direction of the torpedo
    direction = 0  # -1 for left, 0 for straight, 1 for right

    # Initialize the result string
    result = []

    # Iterate over each second
    for _ in range(n):
        # Check if the torpedo hits any ship
        hit = False
        for ship in ships:
            x1, x2, sy = ship
            if y == sy and x1 <= x <= x2:
                hit = True
                break

        if hit:
            return "impossible"

        # Append the current direction to the result
        if direction == -1:
            result.append('-')
        elif direction == 0:
            result.append('0')
        else:
            result.append('+')

        # Move the torpedo
        y += 1

        # Determine the next direction
        if direction == -1:
            if x > 0:
                x -= 1
            else:
                direction = 0
        elif direction == 0:
            if x < 0:
                direction = 1
            elif x > 0:
                direction = -1
        else:
            if x < 0:
                x += 1
            else:
                direction = 0

    return ''.join(result)

