def avoid_ships(n, m, ships):
    # Initialize the DP table
    dp = [None] * (n + 1)
    dp[0] = ('', 0, 0)  # (path, x, y)

    # Sort ships by their y-coordinate
    ships.sort(key=lambda s: s[2])

    for t in range(1, n + 1):
        for ship in ships:
            x1, x2, y = ship
            if y < t:
                continue
            if x1 <= dp[t-1][1] <= x2:
                # Torpedo hit the ship, try to avoid it
                if dp[t-1][1] == x1:
                    # Move right
                    if dp[t-1][2] + 1 == y:
                        dp[t] = (dp[t-1][0] + '+', dp[t-1][1] + 1, dp[t-1][2] + 1)
                        break
                elif dp[t-1][1] == x2:
                    # Move left
                    if dp[t-1][2] + 1 == y:
                        dp[t] = (dp[t-1][0] + '-', dp[t-1][1] - 1, dp[t-1][2] + 1)
                        break
                else:
                    # Move straight
                    if dp[t-1][2] + 1 == y:
                        dp[t] = (dp[t-1][0] + '0', dp[t-1][1], dp[t-1][2] + 1)
                        break
        else:
            # No ship hit, move straight
            dp[t] = (dp[t-1][0] + '0', dp[t-1][1], dp[t-1][2] + 1)

    if dp[n] is None:
        return "impossible"
    else:
        return dp[n][0]

